import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.A5mep7Fe.js";const u=JSON.parse('{"title":"📏 07 · 长上下文与 MoE（混合专家）","description":"","frontmatter":{},"headers":[],"relativePath":"01-算法岗-AIGC与LLM/07-长上下文与MoE.md","filePath":"01-算法岗-AIGC与LLM/07-长上下文与MoE.md","lastUpdated":1786806808000}'),n={name:"01-算法岗-AIGC与LLM/07-长上下文与MoE.md"};function l(i,t,s,d,h,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="📏-07-·-长上下文与-moe-混合专家" tabindex="-1">📏 07 · 长上下文与 MoE（混合专家） <a class="header-anchor" href="#📏-07-·-长上下文与-moe-混合专家" aria-label="Permalink to &quot;📏 07 · 长上下文与 MoE（混合专家）&quot;">​</a></h1><blockquote><p>两个让大模型「更便宜地更大」的关键方向：拉长上下文（能力边界）、MoE（参数扩大但推理省）。</p></blockquote><hr><h2 id="一、长上下文-long-context" tabindex="-1">一、长上下文（Long Context） <a class="header-anchor" href="#一、长上下文-long-context" aria-label="Permalink to &quot;一、长上下文（Long Context）&quot;">​</a></h2><h3 id="为什么难" tabindex="-1">为什么难？ <a class="header-anchor" href="#为什么难" aria-label="Permalink to &quot;为什么难？&quot;">​</a></h3><p>注意力复杂度 $O(n^2)$，n 从 4K→128K→1M，计算与显存爆炸。且位置编码需外推。</p><h3 id="关键技术" tabindex="-1">关键技术 <a class="header-anchor" href="#关键技术" aria-label="Permalink to &quot;关键技术&quot;">​</a></h3><ol><li><strong>位置插值（Position Interpolation, PI） / NTK-aware RoPE</strong>：把训练位置的旋转频率重新缩放，使未见过的长位置「映射」回已训练范围，平滑外推。</li><li><strong>稀疏/滑窗注意力</strong>：局部窗口 + 全局 token，降低复杂度（Mistral 的 Sliding Window）。</li><li><strong>分段/稀疏模式</strong>：Longformer、BigBird 等。</li><li><strong>推理侧</strong>：PagedAttention + KV 量化，支持百万级 KV。</li></ol><h3 id="本质判断" tabindex="-1">本质判断 <a class="header-anchor" href="#本质判断" aria-label="Permalink to &quot;本质判断&quot;">​</a></h3><p>长上下文≠真理解长文本。<strong>「大海捞针」测试</strong>显示，很多模型对中间信息（lost in the middle）利用率低。长上下文是「容量」问题，理解质量还需数据/训练配合。</p><hr><h2 id="二、moe-mixture-of-experts-⭐" tabindex="-1">二、MoE（Mixture of Experts）⭐ <a class="header-anchor" href="#二、moe-mixture-of-experts-⭐" aria-label="Permalink to &quot;二、MoE（Mixture of Experts）⭐&quot;">​</a></h2><p><strong>思想</strong>：把前馈层（FFN）换成<strong>多个专家子网络 + 路由（Router）</strong>，每个 token 只激活其中少数几个专家。</p><ul><li>总参数大（容量大），但每 token 计算量小（只过 k 个专家）→ <strong>参数量与算力解耦</strong>。</li><li>代表：Mixtral 8x7B（8 专家，每 token 激活 2 个，实际效果≈14B 但推理成本≈12B 以下）。</li></ul><h3 id="路由机制" tabindex="-1">路由机制 <a class="header-anchor" href="#路由机制" aria-label="Permalink to &quot;路由机制&quot;">​</a></h3><ul><li>Top-k 路由：token 选分数最高的 k 个专家</li><li>负载均衡损失（Load Balancing Loss）：防止所有 token 都挤少数专家（「专家坍缩」）</li><li>专家容量（capacity）：每专家处理 token 上限，超容则丢弃/缓冲</li></ul><h3 id="优点-代价" tabindex="-1">优点 / 代价 <a class="header-anchor" href="#优点-代价" aria-label="Permalink to &quot;优点 / 代价&quot;">​</a></h3><table tabindex="0"><thead><tr><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>同等算力下更大容量</td><td>显存占用仍大（要存所有专家）</td></tr><tr><td>推理成本随激活专家数</td><td>路由不均、训练不稳定</td></tr><tr><td>适合大规模扩展</td><td>部署/通信复杂（专家并行）</td></tr></tbody></table><hr><h2 id="三、高频追问" tabindex="-1">三、高频追问 <a class="header-anchor" href="#三、高频追问" aria-label="Permalink to &quot;三、高频追问&quot;">​</a></h2><p><strong>Q1：MoE 为什么能「大参数低推理成本」？</strong></p><blockquote><p>参数分布在多个专家，但路由只激活少数，单 token 计算量≈激活专家数 × 单专家，与总专家数无关；代价是显存要装下全部专家。</p></blockquote><p><strong>Q2：为什么需要负载均衡损失？</strong></p><blockquote><p>无约束时路由会偏好少数专家，导致大部分专家不被训练（坍缩），整体容量浪费。均衡损失促使 token 均匀分配。</p></blockquote><p><strong>Q3：长上下文训练和推理的主要瓶颈分别是什么？</strong></p><blockquote><p>训练：注意力 $O(n^2)$ 计算 + 显存；推理：KV Cache 随 n 线性增长的显存 + 单次前向时间。</p></blockquote><hr><p>➡️ 下一步：<a href="./08-主流模型专题">08-主流模型专题</a></p>',28)])])}const g=o(n,[["render",l]]);export{u as __pageData,g as default};
